#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAX_X = 10000;
bool prime[MAX_X + 1];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    fill(prime, prime + MAX_X + 1, true);
    prime[0] = prime[1] = false;

    for(int i = 2; i * i <= MAX_X; i++) {
        if(prime[i]) {
            for(int k = 2 * i; k <= MAX_X; k += i) {
                prime[k] = false;
            }
        }
    }

    int n;
    while (cin >> n && n != 0) {
        int max = -1; // Initialize to -1 to handle the case where no primes are found
        for(int i = n; i >= 3; i--) { // Start from 3 since we are checking for pairs
            if(prime[i] && prime[i - 2]) {
                max = i;
                break;
            }
        }
        if (max != -1) {
            cout << max - 2 << " " << max << "\n"; // Only output if we found a pair
        } else {
            cout << "No prime pairs found\n"; // Handling case where no pairs exist
        }
    }
    return 0;
}

