int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Sieve of Eratosthenes
    fill(prime.begin(), prime.end(), true);
    prime[0] = prime[1] = false;

    for(int i = 2; i * i <= MAX_X; i++) {
        if(prime[i]) {
            for(int k = i * i; k <= MAX_X; k += i) { // Start from i*i to optimize
                prime[k] = false;
            }
        }
    }

    int n;
    while (cin >> n && n != 0) {
        for(int i = n; i >= 3; i--) { // Start from n and go down to 3
            if(prime[i] && prime[i - 2]) {
                cout << i - 2 << " " << i << "\n";
                break;
            }
        }
    }
    return 0;
}

