#include <iostream>
#include <vector>
using namespace std;

const int MAX_X = 10000;
bool prime[MAX_X + 1];
vector<int> twin_primes;

int main() {
    fill(prime, prime + MAX_X + 1, true);
    prime[0] = prime[1] = false;

    for(int i = 2; i * i <= MAX_X; i++) {
        if(prime[i]) {
            for(int k = i * i; k <= MAX_X; k += i) {
                prime[k] = false;
            }
        }
    }

    for(int i = 3; i <= MAX_X; i++) {
        if(prime[i] && prime[i - 2]) {
            twin_primes.push_back(i);
        }
    }

    int n;
    while (cin >> n && n != 0) {
        int max = 0;
        for(int i = twin_primes.size() - 1; i >= 0; i--) {
            if(twin_primes[i] <= n) {
                max = twin_primes[i];
                break;
            }
        }
        cout << max - 2 << " " << max << "\n";
    }
    return 0;
}

